{
  "sections": [
    {
      "key": "verdict",
      "title": "निर्णय",
      "text": "तुमचा दुग्ध व्यवसाय आर्थिक दृष्टीने योग्य आहे. सर्व संकेतक सकारात्मक आहेत."
    },
    {
      "key": "market",
      "title": "बाजार",
      "text": "या गावात अंदाजे {{households}} घरांपर्यंत ग्राहक आहेत. स्पर्धा कमी आहे आणि बाजारातील अंतरही कमी आहे. तुम्ही सहकारी केंद्र, थेट घरांपर्यंत आणि मिठाईच्या दुकानांद्वारे आपला दूध विकू शकता."
    },
    {
      "key": "pricing",
      "title": "किंमत निर्धारण",
      "text": "पहिल्या महिन्यात ब्रेक‑इव्हन होण्याची अपेक्षा {{break_even_month}} महिन्यात आहे. प्रकल्पाची परतफेडीचा कालावधी {{payback_months}} महिने आहे, जो लवकरच मिळेल. नफा आणि रोख प्रवाह चांगले दिसत आहेत."
    },
    {
      "key": "risks",
      "title": "जोखीम",
      "text": "मुख्य जोखीमांमध्ये पशूंची आजारपण, दुधाची किंमत बदल, कर्जाची वेळेवर परतफेड आणि हवामानाचा प्रभाव यांचा समावेश आहे. या जोखीमांना टाळण्यासाठी योग्य आरोग्य देखभाल, किंमत निरीक्षण आणि कर्ज नियोजन आवश्यक आहे."
    },
    {
      "key": "path_to_yes",
      "title": "पुढील पायरी",
      "text": "अभिनंदन! तुमचा प्रकल्प आधीच मान्य आहे. बदलांची गरज नाही."
    },
    {
      "key": "next_steps",
      "title": "पुढील पावले",
      "text": "पहिले, PMEGP योजना अंतर्गत कर्ज {{loan}} आणि अनुदान {{subsidy}} मिळविण्यासाठी अर्ज करा. दुसरे, स्वतःचे योगदान {{own_contribution}} जमा करा. तिसरे, बफेलो खरेदी करा (एकूण खर्च {{cost.animals}}). चौथे, गायींचे शेड बांधा (खर्च {{cost.shed}}). पाचवे, सहकारी केंद्राशी नोंदणी करा आणि वितरणाची योजना तयार करा. शेवटी, नियमित लेखा‑जवाबदारी ठेवून कर्जाची परतफेड करा."
    }
  ],
  "swot": {
    "strengths": [
      "स्थानीय ग्राहकांची मोठी संख्या {{households}}",
      "स्पर्धा कमी आणि बाजारातील अंतर कमी"
    ],
    "weaknesses": [
      "प्रारंभीचा मोठा भांडवली खर्च {{project_cost}}",
      "कर्जाची परतफेडीची जबाबदारी"
    ],
    "opportunities": [
      "PMEGP योजना अंतर्गत अनुदान {{subsidy}}",
      "दूधाची सततची मागणी आणि विविध विक्री चॅनेल"
    ],
    "threats": [
      "पशूंची आजारपण आणि रोग",
      "दुधाच्या बाजारभावातील चढउतार",
      "कर्जावरील व्याजदर बदल"
    ]
  }
}
